#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left``
#         self.right = right
class Solution(object):
    def deleteNode(self, root, key):
        """
        :type root: Optional[TreeNode]
        :type key: int
        :rtype: Optional[TreeNode]
        """
        if root == None:
            return None

        if root.val == key:
            return self.helper(root)

        dummy = root

        while root:
            if(root.val > key):
                # key is on left side

                if root.left and root.left.val == key:
                    root.left = self.helper(root.left)
                else:
                    root = root.left
            else:
                # key is on right side
                if root.right and root.right.val == key:
                    root.right = self.helper(root.right)
                else:
                    root = root.right

        return dummy


    def helper(self, root):
        if root.left == None:
            return root.right
        elif root.right == None:
            return root.left

        rightchild = root.right
        lastright = self.findlastright(root.left)
        lastright.right = rightchild

        return root.left

    def findlastright(self, root):
        if root.right == None:
            return root

        return self.findlastright(root.right)

package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

public class DeleteNodeInABST {

    public TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null;

        if (key < root.val) {
            root.left = deleteNode(root.left, key);
        } else if (key > root.val) {
            root.right = deleteNode(root.right, key);
        } else {
            if (root.left != null && root.right != null) {
                int lmax = max(root.left);
                root.val = lmax;
                root.left = deleteNode(root.left, lmax);
                return root;
            } else if (root.left != null) {
                return root.left;
            } else if (root.right != null) {
                return root.right;
            } else {
                return null;
            }
        }
        return root;
    }

    public int max(TreeNode root) {
        if (root.right != null)
            return max(root.right);
        else
            return root.val;
    }

}

